<?php
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\Database\DatabaseInterface; use Joomla\Database\ParameterType;
final class PkgDecaromembershipInstallerScript { public function postflight($type,$parent):void{if($type!=='install'){return;}try{$db=Factory::getContainer()->get(DatabaseInterface::class);foreach([['xdecaroanalytics','decaromembership'],['task','decaromembership']] as [$folder,$element]){$enabled=1;$query=$db->getQuery(true)->update($db->quoteName('#__extensions'))->set($db->quoteName('enabled').' = :enabled')->where($db->quoteName('type').' = '.$db->quote('plugin'))->where($db->quoteName('folder').' = :folder')->where($db->quoteName('element').' = :element')->bind(':enabled',$enabled,ParameterType::INTEGER)->bind(':folder',$folder)->bind(':element',$element);$db->setQuery($query)->execute();}}catch(\Throwable $e){Factory::getApplication()->enqueueMessage('Membership installed, but optional integration plugins could not be enabled automatically.','warning');}} }
